    public static IReadOnlyList<LibConfigRowPatch> Patches { get; } = [MapInfo, MonsterScenario, TimeTable, Teleport, HarconNpcs];

    public static bool Pending(byte[] xml) =>
        Patches.Any(patch => LibConfigXmlRowEditor.MissingKeys(xml, patch).Count > 0)
        || TimerNpcs.Any(patch => LibConfigXmlRowEditor.FieldsPending(xml, patch));

    public static byte[] Merge(byte[] xml)
    {
        ArgumentNullException.ThrowIfNull(xml);
        foreach (var patch in Patches)
        {
            xml = LibConfigXmlRowEditor.AddMissingRows(xml, patch).Xml;
        }

        foreach (var patch in TimerNpcs)
        {
            xml = LibConfigXmlRowEditor.SetFields(xml, patch);
        }

        return xml;
    }
